  "targets": {
    "dog_bowl_shared": [
      {"days": "weekday", "from": 6.75, "to": 8, "at": "counter_k1", "chance": "usually"},
      {"days": "weekend", "from": 7, "to": 8.5, "at": "counter_k1", "chance": "usually"}
    ],
    "dog_food_bag_shared": [
      {"days": "both", "from": 0, "to": 24, "at": "floor_k_k1", "chance": "usually"}
    ],
