    ],
    "glasses_marco": [
      {"days": "weekday", "from": 8, "to": 9.25, "at": "bathroom_shelf_ba1", "chance": "sometimes"},
      {"days": "weekend", "from": 8, "to": 9.5, "at": "bathroom_shelf_ba1", "chance": "sometimes"}
    ]
  },
  "claims": [
